{'code': "from qgis.PyQt.QtWidgets import QAction
mesh = QgsProject.instance().mapLayersByName('tmp_mesh_edit')[0]
res = {'faces': mesh.meshFaceCount(), 'vertices': mesh.meshVertexCount()}

target = None
for a in iface.mainWindow().findChildren(QAction):
    if a.objectName() == 'mActionSelectIsolatedVertices':
        target = a
        break
res['enabled'] = target.isEnabled()
target.trigger()
res['triggered'] = True
result = res"}

