{'code': "from qgis.gui import QgsVertexMarker, QgsRubberBand
c = iface.mapCanvas()
res = []
for i, it in enumerate(c.items()):
    if isinstance(it, QgsVertexMarker) and it.isVisible():
        ctr = it.center()
        res.append({
            'idx': i, 'class': 'QgsVertexMarker',
            'x': ctr.x(), 'y': ctr.y(),
            'iconType': it.iconType(), 'iconSize': it.iconSize(),
            'color': it.color().name(), 'fillColor': it.fillColor().name(),
        })
    elif isinstance(it, QgsRubberBand) and it.isVisible():
        res.append({'idx': i, 'class': 'QgsRubberBand', 'n': it.numberOfVertices()})
result = res"}

{'code': "from qgis.gui import QgsVertexMarker, QgsRubberBand
c = iface.mapCanvas()
res = []
for i, it in enumerate(c.items()):
    if not it.isVisible():
        continue
    cls = it.metaObject().className()
    entry = {'idx': i, 'class': cls}
    if isinstance(it, QgsVertexMarker):
        ctr = it.center()
        entry.update({'x': ctr.x(), 'y': ctr.y()})
    elif isinstance(it, QgsRubberBand):
        entry['nVertices'] = it.numberOfVertices()
    res.append(entry)
result = res"}

